const GC=2,GR=2;
function d(s){return Math.abs(GC-s.c)+Math.abs(GR-s.r);}
export function initialState(){return {c:0,r:0,moves:0,hint:false,msg:'Reach the orange goal square.'};}
const DIR={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
export function reduce({state,event}){
if(event.type!=='action')return state;
const s={...state};
if(d(s)===0)return s;
if(event.action==='hint'){s.hint=true;s.msg='Follow the green arrow.';return s;}
const v=DIR[event.action];if(!v)return s;
const c=s.c+v[0],r=s.r+v[1];
if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board.';return s;}
s.c=c;s.r=r;s.moves++;s.hint=false;
s.msg=d(s)===0?'You reached the goal in '+s.moves+' moves (shortest: 4).':'Moved '+event.action+'.';
return s;}
const h=Math.SQRT1_2;
export function evaluate({state}){
const s=state||initialState();
const x=(s.c-1)*1.1,z=(1-s.r)*1.1,k=d(s);
const q=s.c<GC?[0,0,-h,h]:[-h,0,0,h];
return {nodes:{token:{position:[x,k===0?0.5:0.45,z]},arrow:{visible:s.hint&&k>0,position:[x,0.45,z],quaternion:q}},
readouts:{moves:s.moves,dist:k},
goal:{status:k===0?'won':'playing',message:s.msg}};}
